def transform(grid):
    import itertools
    g = np.array(grid)
    bg = background(g)
    objs = objects(g, bg=bg)
    objs = sorted(objs, key=lambda o: -o["size"])
    N = 3
    # normalise each object's cells relative to its bounding box
    shapes = []
    for o in objs:
        y0, x0, _, _ = o["box"]
        shapes.append((o["colour"], [(y - y0, x - x0) for y, x in o["cells"]]))

    def offsets(cells):
        h = max(c[0] for c in cells) + 1
        w = max(c[1] for c in cells) + 1
        return [(dy, dx) for dy in range(N - h + 1) for dx in range(N - w + 1)]

    canvas = np.zeros((N, N), dtype=int)
    emit(canvas.copy(), "Allocate an empty 3x3 canvas: the two pieces together have 9 cells.")
    for offs in itertools.product(*[offsets(c) for _, c in shapes]):
        occ = {}
        ok = True
        for (col, cells), (dy, dx) in zip(shapes, offs):
            for y, x in cells:
                p = (y + dy, x + dx)
                if p in occ:
                    ok = False
                    break
                occ[p] = col
            if not ok:
                break
        if ok and len(occ) == N * N:
            out = np.zeros((N, N), dtype=int)
            for i, ((col, cells), (dy, dx)) in enumerate(zip(shapes, offs)):
                for y, x in cells:
                    out[y + dy, x + dx] = col
                if i < len(shapes) - 1:
                    emit(out.copy(), f"Place the larger piece (colour {col}) at offset {(dy, dx)}, leaving holes for the other piece.")
                else:
                    emit(out.copy(), f"Slide the colour-{col} piece into the remaining gaps at offset {(dy, dx)}; the 3x3 square is now fully tiled.")
            return out
    return canvas
